window.MAGIC_CHUNK_3 = [{"name":"Discriminating Cube","aura_strength":"moderate","aura_school":"evocation","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":40000,"weight":0.5,"description":"This cube of force only creates one type of screen, which excludes living matter. Each of the five active faces sets the screen to exclude a different type of living matter (using the same categories as the bane weapon special ability).","requirements":"Craft Wondrous Items, summon monster I, wall of force","cost":20000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Independent Cube of Force","aura_strength":"moderate","aura_school":"evocation","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":70000,"weight":0.5,"description":"The independent cube of force functions exactly like a cube of force except that it remains activated when dropped or set down. Anyone can pick up and deactivate the item or change the active type of wall; otherwise it shuts off when it runs out of charges.","requirements":"Craft Wondrous Items, wall of force","cost":35000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Rechargeable Cube of Force","aura_strength":"moderate","aura_school":"evocation","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":70000,"weight":0.5,"description":"This cube functions like a cube of force except that it can be recharged by casting a wall of force spell into it. Each spell cast in this manner adds 2 charges to the cube. The cube cannot hold more than 36 charges.","requirements":"Craft Wondrous Items, wall of force","cost":35000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Remote Activation Cube","aura_strength":"moderate","aura_school":"evocation","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":70000,"weight":0.5,"description":"This cube can be activated or deactivated from a distance via use of the spell mage hand or the hand of the apprentice ability. The antimagic wall and the wall that keeps out all things prevent remote deactivation in this manner.","requirements":"Craft Wondrous Items, mage hand, wall of force","cost":35000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Twinned Cubes of Force","aura_strength":"moderate","aura_school":"evocation","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":66000,"weight":0.5,"description":"These cubes function as two cubes of force, except that when a face on one cube is pressed, its counterpart creates the appropriate wall instead as long as the distance between the cubes doesn't exceed 100 feet. Both cubes can remain active even after being set down on the ground and abandoned.","requirements":"Craft Wondrous Items, wall of force","cost":33000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"The Elder Decks","aura_strength":"strong","aura_school":"all","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":0,"description":"These ancient artifacts function as decks of many things, save that they have only 13 cards: Euryale, Flames, Jester, Key, Knight, Moon, Rogue, Ruin, Skull, Star, Sun, Throne, and The Void.","requirements":null,"cost":0,"destruction":"An elder deck can be destroyed by losing it in a wager with a deity of law. The deity must be unaware of the nature of the deck.","base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Haykali's House of Cards","aura_strength":"strong","aura_school":"all","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":0,"description":"This item operates as a standard 22-card deck of many things, save that if its wielder takes 5 minutes to build a card house out of its deck (a DC 20 Sleight of Hand check), he and any creatures touching him are instantly transported to a pocket dimension constructed to resemble a massive, fully furnished mansion made out of cards. Within its ever-shifting corridors, the PCs must defeat personifications of the negative cards or be immediately shunted back to the Material Plane and suffer the effects of the card that conquered them. If the PCs successfully reach the heart of the mansion, they find the positive result cards floating there. Each PC may choose one, whereupon he returns to the Material Plane and receives its effects. A creature may enter the House of Cards only once. Designing and mapping the adventure that results from characters entering the House of Cards is left up to the GM; such preparations should take place before introducing this artifact.","requirements":null,"cost":0,"destruction":"Haykali's House of Cards can be destroyed only by surmounting its challenges and then using the Moon card to wish for the deck's destruction.","base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Helm of Reclamation","aura_strength":"strong","aura_school":"varies","cl":15,"slots":["head"],"groups":["Wondrous Item"],"price":80000,"weight":3,"description":"The helm of reclamation is designed to destroy large groups of undead or powerful individual undead creatures, and is often used by undead-hating clerics with a flair for the dramatic. The gems of this helm produce sunburst (10 yellow diamonds), searing light (30 bloodstones), and daylight (40 opals). Like a standard helm of brilliance, it glows near and harms undead, and has the flaming weapon ability, but doesn't protect against fire or risk detonation.","requirements":"Craft Wondrous Items, daylight, detect undead, flame blade, searing light, sunburst","cost":40000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Aligned Horn of Valhalla","aura_strength":"strong","aura_school":"conjuration","cl":13,"slots":["none"],"groups":["Wondrous Item"],"price":45000,"weight":2,"description":"This horn of Valhalla is crafted for service to a cause, whether lofty or profane. Though not intelligent, it has an alignment as determined by the Intelligent Item Alignment table, and summons barbarians of that alignment. A character who sounds the horn but is more than one step away from the horn's alignment is attacked by the summoned barbarians. The horn's minions also turn against an owner who gives them an order in strong opposition to their ethos, such as ordering lawful good barbarians to attack helpless villagers.","requirements":"Craft Wondrous Items, summon monster VI","cost":25000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Linnorm's Lament","aura_strength":"strong","aura_school":"conjuration","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":2,"description":"This horn operates as a normal horn of Valhalla, save that it can be blown more than once per day, with the warriors from previous soundings remaining until their 1 hour has passed. When the wielder blows the horn for the third time, he becomes destined to die before the next dawn, with chance-based events turning against him in more and more improbable ways until he's slain. The manner of this curse and any potential methods of defeating it are left to the GM.","requirements":null,"cost":0,"destruction":"Linnorm's Lament shatters if someone blows it a third time and survives for 1 year afterward.","base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Sphere of Bleeding Snowflakes","aura_strength":"strong","aura_school":"transmutation","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":0,"description":"This sphere originates within the Negative Energy Plane as either a naturally occurring phenomenon or a normal sphere of annihilation empowered or even damaged by beings there. The sphere of bleeding snowflakes radiates a cold, dense fog of black energy extending 60 feet into its surrounding area, infusing the region with negative energy, and dealing 4d6 negative energy damage (as a cleric's channeled energy) and 1 permanent negative level per round to everything within 60 feet. While spells such as death ward may negate the energy's ill effects, any who die as a result of these effects, or who die by other means within the sphere's affected radius, cannot be returned to life by anything short of true resurrection, wish, or miracle.","requirements":null,"cost":0,"destruction":"The sphere of bleeding snowflakes can be destroyed by sending it through one of the portals on the Positive Energy Plane leading into the heart of a star.","base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Twin Spheres","aura_strength":"strong","aura_school":"transmutation","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":0,"description":"Rumored to have once been a single, normal sphere split in two through a failed attempt to destroy it, these dual spheres of annihilation are linked, such that objects devoured by one may be disgorged from the other. Anything devoured by one of the twin spheres must make a Fortitude save (DC 25) or be utterly consumed as by a normal sphere; anything that makes the save take 10d6 points of damage in transit and is hurled, smoking and partially disintegrated, from the maw of the other sphere. Anyone currently in mental control of one sphere may freely pass through it to the location of its twin.","requirements":null,"cost":0,"destruction":"The twin spheres can be destroyed by directing one sphere through the other, causing an explosion that deals 20d6 damage to everything within 100 feet.","base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Rift-Born Sphere","aura_strength":"strong","aura_school":"transmutation","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":0,"description":"This sphere acts as a normal sphere of annihilation in all respects, save that any use of a gate spell to destroy it results in an automatic planar rift to a plane of the GM's choosing. The sphere remains behind at its original location, intact and unaffected.","requirements":null,"cost":0,"destruction":"A rift-born sphere can only be destroyed by using a rod of cancellation or fusion with another, normal sphere (which destroys both spheres in a 180-foot blast dealing 5d6 x 10 points of damage).","base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Magi Staff of the Mammoth","aura_strength":"strong","aura_school":"all","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":5,"description":"Seven feet of twisted, gnarled spruce carved with primitive runes and icons depicting mammoths, tigers, and hunters form this regal staff. The staff has all the powers of a staff of the magi with the following changes:\n- sleet storm (instead of fireball)\n- fog cloud (instead of pyrotechnics)\n- wall of ice (instead of wall of fire) The staff can also cast cone of cold (15d6 damage, Reflex DC 19 half) for a cost of 2 charges. When casting summon monster IX, the staff of the mammoth always summons 1d4+1 celestial or fiendish mastodons.","requirements":null,"cost":0,"destruction":"This item can be destroyed in the same manner as a normal staff of the magi.","base_item":"quarterstaff","magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Magi Staff of the Deep Black","aura_strength":"strong","aura_school":"all","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":5,"description":"This crystalline blue-white staff fell from the sky during a dazzling display of falling stars. Sages believe it was once part of an enormous piece of ice drifting between worlds since the dawn of time, only coming to the world on a quirk of chance. Though as hard as crystal, the staff feels like wet ice, is cold to the touch, and gives the impression of great age. It slowly sinks in fresh or salt water (unlike true ice, which floats), and while it creates a cocoon of ice around itself when submerged, it is only after several hours that this coating is thick enough to cause the staff to bob to the surface. The staff's powers (and the equivalent staff of the magi powers they replace) are:\n- ray of frost (detect magic, 0 charges)\n- reduce person (enlarge person, 0 charges)\n- cone of cold (fireball, 1 charge)\n- freezing ray (knock, functions as scorching ray but deals cold damage, 1 charge)\n- water breathing (lightning bolt, 1 charge)\n- fly (passwall, 1 charge)\n- wall of ice (wall of fire, 1 charge)\n- teleport (passwall, 2 charges)\n- time stop (monster summoning IX, 2 charges) The staff otherwise has the normal powers and abilities of a staff of the magi. If it is broken in a retributive strike, the bearer has a 25% chance to be held in stasis somewhere (as imprisonment, no saving throw), a 25% chance to be transported to a random plane, and a 50% chance to be utterly destroyed.","requirements":null,"cost":0,"destruction":"This item can be destroyed in the same manner as a normal staff of the magi. It is also destroyed if consumed by an elder fire elemental or an efreeti, or if cast into an active volcano.","base_item":"quarterstaff","magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Magi Staff of the Necromancer","aura_strength":"strong","aura_school":"all","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":5,"description":"This long staff of smooth, pale bone is bent in a swaying shape, like a crone's back, and is carved with ancient symbols of death and spirits, with the writing standing out in stark black from a thick paste of human ash rubbed into it. Any good creature who holds or carries the staff gains two permanent negative levels (similar to holding an unholy weapon). The staff's powers (and the equivalent staff of the magi powers they replace) are:\n- detect undead (detect magic, 0 charges)\n- disrupt undead (enlarge person, 0 charges)\n- spectral hand (knock, 1 charge)\n- vampiric touch (lightning bolt, 1 charge)\n- animate dead (wall of fire, 1 charge)\n- finger of death (plane shift, 2 charges)\n- energy drain (monster summoning IX, 2 charges) The staff otherwise has the normal powers and abilities of a staff of the magi. If broken in a retributive strike, the bearer has a 25% chance to be transported to the Negative Energy Plane, a 50% chance to be transported to a random plane, and a 25% chance to be utterly destroyed. Rumor has it that the staff contains a hollow space to hold a lich's phylactery, though arcane scholars point out that no sane lich would keep his life essence in a magic item that explodes when broken.","requirements":null,"cost":0,"destruction":"This item can be destroyed in the same manner as a normal staff of the magi. It is also destroyed immediately if a good cleric casts heal on the staff while on the Positive Energy Plane.","base_item":"quarterstaff","magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Magi Staff of the Scholar","aura_strength":"strong","aura_school":"all","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":5,"description":"This shepherd's crook is formed of alternating bands of ivory and obsidian around a sycamore shaft. Golden runes run the length of the staff, twisting into new configurations as its various powers are used. The staff of the scholar has all the powers of a regular staff of the magi plus the following abilities: contact other plane (2 charges), legend lore (2 charges), and scrying (2 charges). If the wielder of the staff of the scholar uses its retributive strike ability and successfully travels to another plane of existence, he always arrives in the abode of a god of knowledge (though not necessarily a friendly one).","requirements":null,"cost":0,"destruction":"This item can be destroyed in the same manner as a normal staff of the magi.","base_item":"quarterstaff","magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Staff of Elemental Castigation","aura_strength":"strong","aura_school":"all","cl":20,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":5,"description":"This staff functions as a staff of the magi, with several modifications. Its summon monster IX power can only summon elementals, and it has the following powers\n- summon monster IV (elementals only, 1 charge)\n- elemental body IV (2 charges)\n- planar binding (elementals only, 2 charges) Whenever the staff is broken in a retributive strike, it automatically reforms, but can never again be wielded by its previous possessor. A wielder transported to another plane by a retributive strike always appears on an elemental plane, while the staff itself is sent to a different elemental plane moments after reforming.","requirements":null,"cost":0,"destruction":"This item can be destroyed by having elementals from all four elemental planes (earth, air, fire, and water) attack it at the same time while it is broken in a retributive strike.","base_item":"quarterstaff","magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Executioner's Hand","aura_strength":"strong","aura_school":"necromancy and transmutation","cl":18,"slots":["none"],"groups":["Weapon"],"price":75000,"weight":8,"description":"This +3 adamantine greatsword is designed with a single purpose: to bring swift death to those tried and found guilty before the law. When wielded in a coup de grace attempt against a helpless target, the executioner's hand is treated as a vorpal weapon, and if the attack is a critical threat, it is automatically confirmed as a critical hit.","requirements":"Craft Magic Arms and Armor, circle of death, keen edge","cost":39000,"destruction":null,"base_item":"+3 adamantine greatsword","magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Frostkiss Whip","aura_strength":"strong","aura_school":"necromancy and transmutation","cl":18,"slots":["none"],"groups":["Weapon"],"price":128300,"weight":2,"description":"Ice covers the lash of this +1 frost vorpal whip. A frostkiss whip deals damage as though it were one size category larger (1d3 for a Small whip, 1d4 for a Medium whip, and so on). In addition, on command a frostkiss whip deals lethal damage instead of nonlethal damage, and it can deal damage even against creatures with armor bonuses greater than +1 or natural armor bonuses higher than +3.","requirements":"Craft Magic Arms and Armor, chill metal or ice storm, horrid wilting, keen edge","cost":64300,"destruction":null,"base_item":"+1 frost vorpal whip","magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Jorngarl's Harm","aura_strength":"strong","aura_school":"necromancy [evil] and transmutation","cl":18,"slots":["none"],"groups":["Weapon"],"price":150320,"weight":24,"description":"This Large +2 keen vorpal greataxe has an adamantine haft and a chipped, pitted guillotine blade instead of a curved axehead. Obviously made for a giant's hands, the axe laughs evilly whenever it kills. Like the final blades of Galt, any creature killed by it (whether from decapitation or simple damage) finds its soul trapped within the blade, and it cannot be raised from the dead while so trapped. Presumably the Gray Gardeners would know how to release a soul from the blade.","requirements":"Craft Magic Arms and Armor, circle of death, enervation, keen edge","cost":75320,"destruction":null,"base_item":"+2 keen vorpal greataxe","magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Liar's Well","aura_strength":"strong","aura_school":"conjuration","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":84250,"weight":0,"description":"When opened, this cursed well of many worlds has a 50% chance of displaying a false image of its destination. For example, the well may appear to open onto the plane of Axis while in reality opening onto a layer of the Abyss, though the difference isn't always to the user's detriment. Any creatures emerging from the other side are not subject to the illusion. The false image is defeated by a true seeing spell.","requirements":"Craft Wondrous Items, gate, mirage arcana","cost":42125,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Shadow Well","aura_strength":"strong","aura_school":"conjuration","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":82000,"weight":0,"description":"Rather than opening to random locations across the planes, the shadow well opens only to random locations on the Shadow Plane (or random locations on the Material Plane when on the Shadow Plane). Regardless of which plane the user opens the well from, there is a 15% chance it randomly diverts the user into the Ethereal Plane, given its nature as a natural buffer between the two realities.","requirements":"Craft Wondrous Items, gate, shadow walk","cost":41000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Well of Stars","aura_strength":"strong","aura_school":"conjuration","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":60000,"weight":0,"description":"Rather than opening to locations on different planes, this well instead opens to worlds on the Material Plane. It doesn't, however, necessarily open to worlds with similar environments to that of its user; hence it can pose much the same danger as the traditional well in terms of both the unpredictable environs of the destination and the alien beings that might step through from the other side.","requirements":"Craft Wondrous Items, gate","cost":30000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Well of the Welcome Respite","aura_strength":"strong","aura_school":"conjuration","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":122000,"weight":0,"description":"While normally functioning as a standard well of many worlds, this well possesses a command word that supersedes its normal placement-based destination, and it instead opens up onto a single location designated by its maker during the well's creation (often the creator's home or a private, warded demiplane). Those finding the well are not immediately aware of this command word unless a spell more powerful than a simple identify spell is used, and the well's secret destination, whatever it might be, may or may not still be occupied.","requirements":"Craft Wondrous Items, gate, mage's magnificent mansion","cost":61000,"destruction":null,"base_item":null,"magic_items":null,"source":"Classic Treasures","pfs_content":0},{"name":"Nesa's Coin","aura_strength":"faint","aura_school":"divination","cl":1,"slots":["none"],"groups":["Wondrous Item"],"price":450,"weight":0,"description":"This simple copper coin establishes a connection with the most recent person to keep it under his tongue for 24 hours. Once established, this connection allows its owner to determine its current direction and distance each time he casts detect magic. The connection instantly breaks if the coin travels to another plane or enters an antimagic field.","requirements":"Craft Wondrous Items, detect magic","cost":225,"destruction":null,"base_item":null,"magic_items":null,"source":"Gnomes of Golarion","pfs_content":0},{"name":"Oculus of Abaddon","aura_strength":"overwhelming","aura_school":"conjuration, divination, and necromancy","cl":20,"slots":["eyes"],"groups":["Artifact, Minor"],"price":0,"weight":1,"description":"An oculus of Abaddon is a potent artifact rumored to have been created by one of the Four Horsemen of the Apocalypse as a way to reward those who work as their agents on the Material Plane. More likely, these items were crafted by a powerful pre-Earthfall race that has long since moved on, leaving behind these dangerous artifacts to tempt mortals into serving the needs of the Horsemen. An oculus of Abaddon appears as a sphere of clear crystal that contains a pinpoint of flickering red light at its center. When held, the oculus feels warm to the touch and fills the holder with a sudden desire to pluck out an eye and place the oculus within the socket-this causes 1d8 points of damage, 1 point of bleed damage, and 2 points of Constitution damage. Once placed in an eye socket, the oculus can only be removed by ripping it free (causing the same amount of damage as the initial plucking). An oculus placed in an empty eye socket immediately heals all damage caused by plucking the previous eye out. Once placed, an oculus allows its new owner to utilize its powers, as listed below.\n- Darkvision to a range of 120 feet (constant)\n- True seeing once per day as a free action\n- Greater scrying three times per day\n- Planar binding once per week (only to summon natives of Abaddon, such as daemons or soul eaters)\n- Familiar farsight at will (if the user has a familiar or an animal companion, he may use clairaudience/clairvoyance to observe the world through his familiar, despite any intervening distance as long as he and the familiar are on the same plane) The oculus of Abaddon's greatest power, though, is its haunting beckon. This ability is usable once per year, and allows the user to manipulate the minds of a huge number of targets, provided that the end goal of the manipulation is a tragic or otherwise horrific fate for those being manipulated. This functions as mass charm monster, but with a range of 1 mile, and establishes a telepathic link between the caster and all minds in that area. The effects are still language-dependant despite this telepathy-creatures without the ability to understand language (typically, creatures with an Intelligence score of 2 or lower) are unaffected. All other creatures are automatically affected unless they have 6 or more HD, in which case they gain a DC 22 Will save to resist the effects. Spell resistance applies regardless of HD. The oculus of Abaddon is powerfully neutral evil and possesses a limited and hateful intellect of its own. While not capable of communicating directly with its owner, it refuses to activate its powers for any user who isn't neutral evil.","requirements":null,"cost":0,"destruction":"A foul and hideous object, the oculus of Abaddon is fortunately relatively easy to destroy, as far as artifacts go. To destroy an oculus of Abaddon, it must be smashed by a bludgeoning holy weapon wielded by a permanently blinded humanoid-alternatively, any bludgeoning weapon wielded by a permanently blinded good outsider with at least 7 HD will work as well. A DC 30 Knowledge (arcana) check is enough to learn this method of destruction.","base_item":null,"magic_items":null,"source":"AP 33","pfs_content":0},{"name":"Beguiling Bangles","aura_strength":"moderate","aura_school":"enchantment","cl":7,"slots":["neck"],"groups":["Wondrous Item"],"price":11000,"weight":0,"description":"Originally created by the Varisians, this elaborate silver and glass necklace renders the wearer immune to any magical effect that detects lies and grants the wearer a +2 bonus on Will saves to resist any magic that would compel him to tell the truth. The necklace grants the wearer a +5 competence bonus on Bluff checks made to deceive (but not create a diversion or feint).","requirements":"Craft Wondrous Items, glibness","cost":5500,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Chest of Preparedness","aura_strength":"moderate","aura_school":"conjuration","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":5000,"weight":30,"description":"Created by the Prophets of Kalistrade, this chest is approximately 2 feet wide and 1 foot long. On creation, the maker chooses 10 nonmagical items worth under 100 gp that could fit within the chest's dimensions. They can be specially created items for the chest (such as a silvered dagger) or a standard item (such as 50 feet of silk rope). Thereafter, when the box is closed, the owner need only speak the name of one of the items, and it appears within the chest, ready to be removed and used. A given item only appears once per day, and disappears after 24 hours. Prophets use these chests to keep backups of important tools, and to hide weapons in case of emergency.","requirements":"Craft Wondrous Items, minor creation","cost":2500,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Crowcaller","aura_strength":"faint","aura_school":"necromancy","cl":8,"slots":["none"],"groups":["Weapon"],"price":29110,"weight":10,"description":"The Ulfen Guard favor a single-bladed battleaxe as their weapon of choice. An elite few are chosen to bear a crowcaller, a magically enhanced version that not only strikes down assassins, but also helps track the assassins' masters. A crowcaller is a +2 keen greataxe. Once per day, if the axe is laid across the chest of a foe it has slain, it compels the corpse to answer five questions as per the speak with dead spell.","requirements":"Craft Magic Arms and Armor, keen edge, speak with dead","cost":14710,"destruction":null,"base_item":"+2 keen greataxe","magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Daring Dancers","aura_strength":"moderate","aura_school":"transmutation","cl":8,"slots":["feet"],"groups":["Wondrous Item"],"price":16000,"weight":0,"description":"These glittering anklets or spurs are favorites of Varisians, both for their showy addition to performances and their more practical uses. Normally made of metal and leather and adorned with glass beads or small gemstones, they make the wearer's feet light and agile, granting a +5 competence bonus to Perform (dance) checks. The wearer's footfalls become so light that he can dance gracefully on any surface and make a 5-foot step even in difficult terrain. If the wearer has 5 or more ranks in Perform (dance), daring dancers allow him to cast dimension door on himself once per day to travel up to 700 feet.","requirements":"Craft Wondrous Items, dimension door, creator must have 10 ranks in Perform (dance)","cost":8000,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Disk of Ghol-Gan","aura_strength":"moderate","aura_school":"conjuration (teleportation)","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":24000,"weight":3,"description":"Excavated within the Shackles among the temples of its lost Ghol-Gan culture, these stone disks display whorls of symbols in the dead language of that dead kingdom, centered about a sphere of black volcanic glass. Each disk acts as a word of recall spell when the command word is spoken; each disk is keyed to a specific island in the territory once controlled by the people of Ghol-Gan. The disk functions once per day, and its destination cannot be changed. Most of these are in the hands of Shackles pirate lords.","requirements":"Craft Wondrous Items, word of recall","cost":12000,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum I","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":500,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of 1st-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":250,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum II","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":2000,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of up to 2nd-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":1000,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum III","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":4500,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of up to 3rd-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":2250,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum IV","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":8000,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of up to 4th-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":4000,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum V","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":12500,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of up to 5th-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":6250,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum VI","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":18000,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of up to 6th-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":9000,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum VII","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":24500,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of up to 7th-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":12250,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum VIII","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":32000,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of up to 8th-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":16000,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Guiding Vellum IX","aura_strength":"moderate","aura_school":"divination","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":40500,"weight":0.5,"description":"Fashioned from soft yet still quite durable lambskin, this piece of parchment gives a faithful divine spellcaster of a specific religion a hint about what spell may be useful for that day (GM discretion). Each day, when the owner prepares spells in the presence of the guiding vellum, the name of one specific divine spell of up to 9th-level which the owner already has the ability to cast appears on its surface. This represents a spell which should prove useful for the tasks in the next 24 hours.\n\nA caster can only use one vellum of a particular spell level each day (using two 1st-level vellums gives the same result), but using vellums of different spell levels works normally. Each vellum works only once per day. A guiding vellum normally doesn't work for a character not of the item's specific religion; some religions add additional magic so a vellum used by a hostile or rival faith provides misleading spell suggestions.","requirements":"Craft Wondrous Items, divination","cost":20250,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Home Stone","aura_strength":"moderate","aura_school":"conjuration (teleportation)","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":2250,"weight":1,"description":"When the command word is spoken, this palm-sized stone teleports one Medium creature and up to 100 pounds of equipment to a specific elf gate that the stone is keyed to. Only one creature may travel this way per home stone. The stone crumbles when activated. Home stones were originally invented by the Lantern Bearers as a way to quickly escape the Darklands when raids went poorly, with a typical raiding party carrying only one such stone, allowing a lone survivor to return and report on the mission.","requirements":"Craft Wondrous Items, teleport","cost":1125,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Ki Crystal","aura_strength":"moderate","aura_school":"transmutation","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":2000,"weight":0,"description":"Created by the masters within the Kusari-Gama faction, this thumbnail-sized crystal stores a single point of ki. Any person with the ki pool ability may expend the stored ki as if using his own ki. Once the ki is expended, the crystal shatters. In Minkai, the Kusari-Gama monks sometimes craft ki crystals into the hilts of powerful weapons. In Vudra, such crystals are often embedded in small animal statuettes or in shrines venerating a favored deity.","requirements":"Craft Wondrous Items, ki pool, Kusari-Gama 40 TPA","cost":1000,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Midsummer Sickle","aura_strength":"moderate","aura_school":"evocation","cl":12,"slots":["none"],"groups":["Weapon"],"price":7806,"weight":1,"description":"Created by the druids of the Green Faith, this +1 mithral spell storing sickle serves as a divine focus for druids. It can only store spells on the druid spell list or from the Air, Earth, Fire, or Water domains or nature bond domain lists.","requirements":"Craft Magic Arms and Armor, creator must be a druid of at least 12th level","cost":4306,"destruction":null,"base_item":"+1 mithral spell storing sickle","magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Utilitarian Rod","aura_strength":"moderate","aura_school":"transmutation","cl":8,"slots":["none"],"groups":["Rod"],"price":5000,"weight":5,"description":"Created by the Arcanamirium, this plain wooden rod is capped with steel, with 10 buttons along its length; it looks rugged and is usually scratched and stained. Pushing any of the buttons is an action equivalent to drawing a weapon. Unless otherwise stated, pressing a button a second time reverts the rod to its basic form. The following functions have no limit on the number of times they can be employed. Brace/jack: The end caps flatten into 2-foot-diameter discs and the wooden haft extends up to 10 feet, creating a brace for a tunnel ceiling or lifting a heavy object 10 feet into the air. Bridge: The rod flattens and extends to 1 foot wide, 1 inch thick, and 12 feet long. This form can support 4,000 pounds. Climbing pole/ladder. A spike that can anchor in stone extrudes from one end, while the other sprouts three sharp hooks. The rod lengthens to anywhere between 5 and 50 feet in a single round. Horizontal bars 3 inches long fold out from the sides, 1 foot apart, in staggered progression. The rod is firmly held by the spike and hooks and can bear up to 4,000 pounds. Crowbar: This functions like a normal crowbar. Drill: One metal cap extends to a drill-like point and begins to spin, easily drilling a 3-inch-diameter hole through 3 feet of wood or 1 foot of stone per minute. Mallet: Though not intended as a weapon, a character can attack with the rod in this form as if it were a Medium warhammer with a -2 penalty. Portable ram: This functions like a normal portable ram, except up to three people are needed to help the wielder. Saw: This works like a normal two-person saw. Shovel: Pressing this button makes the rod cycle between a short-handled shovel, a long-handled shovel, and its basic form. Wedge: One metal cap extends to form a flat chisel shape, such as for cutting wood or breaking stone (normally a hammer or mallet is used with it for this task).","requirements":"Craft Rod, fabricate, polymorph any object","cost":2500,"destruction":null,"base_item":null,"magic_items":null,"source":"Faction Guide","pfs_content":0},{"name":"Armillary Amulet","aura_strength":"faint","aura_school":"divination","cl":5,"slots":["neck"],"groups":["Wondrous Item"],"price":2500,"weight":0,"description":"This thin chain of silvery-gray metal holds a series of interlocking rings that slowly turn within themselves in an accurate replication of the celestial sphere. The amulet grants its wearer a +5 competence bonus on Spellcraft checks. It also grants immunity to the dangerous effects of the Orrery of Nal-Kashel.","requirements":"Craft Wondrous Items, creator must have 5 ranks in the Spellcraft skill","cost":1250,"destruction":null,"base_item":null,"magic_items":null,"source":"From Shore to Sea","pfs_content":0},{"name":"Elixir of True Form","aura_strength":"moderate","aura_school":"abjuration","cl":8,"slots":["none"],"groups":["Wondrous Item"],"price":1600,"weight":0,"description":"This elixir removes all curses and transmutation effects from the imbiber, including the unnatural mutations resulting from the arcane warping of the island of Nal-Kashel or gained through an ancestor's unspeakable interbreeding with ulat-kini. The elixir stops gillmen from transforming into skum but cannot reverse the transformation if a gillman has already become a skum. Only doses of the elixir manufactured on the island of Nal-Kashel can remove the warping effects of the island's influence.","requirements":"Craft Wondrous Items, remove curse","cost":800,"destruction":null,"base_item":null,"magic_items":null,"source":"From Shore to Sea","pfs_content":0},{"name":"Cloak of the Jungle","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["shoulders"],"groups":["Wondrous Item"],"price":2400,"weight":1,"description":"When this plain green cloak is worn with the hood drawn up around the head, the wearer can assume the form of a Large tree or shrub, as per the tree shape spell. The cloak is usable once per day, and the wearer may remain in tree form for up to 1 hour. The wearer can return to his normal form as a free action.","requirements":"Craft Wondrous Items, tree shape","cost":1200,"destruction":null,"base_item":null,"magic_items":null,"source":"Sargava","pfs_content":0},{"name":"Expedition Pavilion","aura_strength":"faint","aura_school":"evocation","cl":5,"slots":["none"],"groups":["Wondrous Item"],"price":6400,"weight":10,"description":"This ordinary-looking, windowless tent appears to cover only a 10-foot by 10-foot area, but, inside, it measures a full 30 feet by 30 feet, with a large central area and three small \"bedrooms\" (separated by curtains) along the back wall. The interior can be lit on command, and can be adjusted from normal darkness as per the spell light. Occupants inside the tent cannot be seen, heard, or smelled by creatures outside. The temperature inside the expedition pavilion is 70° F if the exterior temperature is between 0 and 100° F. For every degree the exterior temperature is below 0 or above 100, the interior temperature decreases or increases, respectively, by 1. The pavilion also provides protection against the elements, such as rain, dust, and sandstorms. The pavilion withstands any wind of less than hurricane force, but a hurricane (75+ mph wind speed) or greater force destroys it. The pavilion can only be set up once per day, requiring 10 minutes to erect or dismantle. The tent cannot be dismantled while foreign objects are still inside, though if the pavilion is destroyed, any creatures and objects inside immediately spill out.","requirements":"Craft Wondrous Items, hide from animals, tiny hut","cost":3200,"destruction":null,"base_item":null,"magic_items":null,"source":"Sargava","pfs_content":0},{"name":"Jungle Boots","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["feet"],"groups":["Wondrous Item"],"price":6000,"weight":1,"description":"These soft leather boots grant the wearer the ability to move through normal undergrowth without hindrance as if he had the woodland stride ability.","requirements":"Craft Wondrous Items, longstrider, woodland stride ability","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Sargava","pfs_content":0}];
